INSERT dbo.account_transaction(AccountID,Amount,TransactionType) VALUES(1,500,'Credit'),(2,200,'Debit'); UPDATE dbo.account_transaction SET Amount=550 WHERE TransactionID=1; DELETE dbo.account_transaction WHERE TransactionID=2; SELECT * FROM dbo.account_tx_audit ORDER BY AuditID; BEGIN TRY UPDATE dbo.vw_savings_accounts SET Balance=CASE WHEN AccountID=4 THEN -100 ELSE Balance+100 END; END TRY BEGIN CATCH SELECT ERROR_MESSAGE() ExpectedError; END CATCH; SELECT * FROM dbo.accounts ORDER BY AccountID; SELECT name,is_recursive_triggers FROM sys.databases WHERE name=DB_NAME(); -- Avoid self-updating trigger loops; use TRIGGER_NESTLEVEL() guard and/or disable recursion carefully.